CREATE OR REPLACE FUNCTION marketplace."listOpportunities"(input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace AS $$
DECLARE p marketplace."ProviderProfile";
BEGIN
 PERFORM marketplace.require_actor();
 SELECT * INTO p FROM marketplace."ProviderProfile" WHERE id=(input->>'provider_profile_id')::uuid AND created_by_id=marketplace.actor_id();
 IF NOT FOUND OR p.verification_status<>'approved' THEN RAISE EXCEPTION 'Approved provider access required' USING ERRCODE='42501'; END IF;
 IF p.availability<>'online' THEN RETURN '[]'; END IF;
 RETURN coalesce((SELECT jsonb_agg(v ORDER BY (v->>'distance')::float8) FROM (SELECT jsonb_build_object('id',r.id,'reference',r.reference,'category_slug',r.category_slug,'category_name',r.category_name,'description',r.description,'suburb',r.suburb,'city',r.city,'urgency',r.urgency,'scheduled_for',r.scheduled_for,'budget_hint_cents',r.budget_hint_cents,'attachments',r.attachments,'status',r.status,'created_date',r.created_date,'distance',round(marketplace.distance_km(p.latitude,p.longitude,r.latitude,r.longitude)::numeric,1),'age',greatest(0,extract(epoch FROM now()-r.created_date)::bigint)) v FROM marketplace."ServiceRequest" r WHERE r.status='open' AND r.created_by_id<>p.created_by_id AND r.category_slug=ANY(p.category_slugs) AND marketplace.distance_km(p.latitude,p.longitude,r.latitude,r.longitude)<=p.service_radius_km AND (r.scheduled_for IS NULL OR r.scheduled_for>now()) AND (r.urgency<>'emergency' OR p.emergency_available) AND NOT EXISTS(SELECT FROM marketplace."Bid" b WHERE b.request_id=r.id AND b.provider_profile_id=p.id)) rows),'[]');
END $$;
CREATE FUNCTION marketplace.notify_submission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace,public AS $$ DECLARE admin_user record; BEGIN IF NEW.verification_status='submitted' AND (TG_OP='INSERT' OR OLD.verification_status<>'submitted') THEN FOR admin_user IN SELECT email FROM public."User" WHERE role='ADMIN' LOOP PERFORM marketplace.notify(admin_user.email,'Provider verification submitted',NEW.display_name||' is ready for review.','verification','/admin'); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_submission AFTER INSERT OR UPDATE ON marketplace."ProviderProfile" FOR EACH ROW EXECUTE FUNCTION marketplace.notify_submission();
CREATE FUNCTION marketplace.notify_review_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace AS $$ DECLARE email text; BEGIN SELECT user_email INTO email FROM marketplace."ProviderProfile" WHERE id=OLD.provider_profile_id; PERFORM marketplace.notify(email,'Customer review updated','A customer review has been '||CASE WHEN TG_OP='DELETE' THEN 'removed.' ELSE 'updated.' END,'review','/provider');RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END $$;
CREATE TRIGGER notify_review_change AFTER UPDATE OR DELETE ON marketplace."Review" FOR EACH ROW EXECUTE FUNCTION marketplace.notify_review_change();
REVOKE ALL ON FUNCTION marketplace.notify_submission(),marketplace.notify_review_change() FROM PUBLIC;
